-- composition of rule kernels P:CombinePartialFinalAggregate x P:ProjectionPushdown (datafusion), template product
SELECT count(*) FROM (SELECT '2000-01-01'::date AS c0 FROM (t4 AS a1 JOIN t4 AS a2 ON (a1.c0 = a2.c0)) GROUP BY a2.c3, a1.c0 UNION ALL (SELECT '2024-01-01'::date AS c0 UNION SELECT '2000-01-01'::date AS c0)) AS ka CROSS JOIN (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT MIN (CASE WHEN (SELECT BOOL_AND (FALSE) FROM tp AS a2) THEN a1.c0 ELSE a1.c0 END) AS c0, 5e-324::float8 AS c1 FROM t0 AS a1 GROUP BY CUBE (a1.c0)) AS kb;
